/**
 * Calculates cosine similarity between 2 embedding vectors.
 *
 * Result:
 * - 1   = very similar / same direction
 * - 0   = unrelated
 * - -1  = opposite meaning (rare for embeddings)
 */
function cosineSimilarity(a, b) {
  // Dot product = how much the vectors point in the same direction
  let dot = 0;
  // Magnitude (length) of the vectors
  let magA = 0;
  let magB = 0;

  for (let i = 0; i < a.length; i++) {
    // Multiply matching dimensions and sum them
    dot += a[i] * b[i];

    // Sum squared values to calculate vector length later
    magA += a[i] * a[i];
    magB += b[i] * b[i];
  }

  /**
   * Final cosine similarity formula:
   *
   *            dot product
   * --------------------------------
   * magnitude(A) × magnitude(B)
   *
   * Why:
   * This normalizes the score so it reflects direction similarity,
   * not just vector size.
   */
  const denom = Math.sqrt(magA) * Math.sqrt(magB);

  /**
   * Prevent division by zero.
   *
   * If one vector is empty or invalid, magnitude becomes 0,
   * and cosine similarity would break.
   *
   * In that case, return 0 (no similarity).
   */
  return denom === 0 ? 0 : dot / denom;
}




/**
 * No meaningful content — skip calculation and force similarity to 0
 */
if (!((($json.title || '') + ($json.snippet || $json.article || '')).trim()))
  return {
    json: {
      ...article,
      similarityScore: 0 
    } 
  };

/**
 * Get embeddings from incoming n8n JSON.
 *
 * embeddings[0] = article embedding
 * embeddings[1] = user interest embedding
 */
const embeddings = $json.embeddings || [];

/**
 * Extract vectors safely.
 *
 * Fallback to [] so the workflow doesn't crash
 * if one embedding is missing.
 */
const articleEmb = embeddings[0] || [];
const interestEmb = embeddings[1] || [];

/**
 * Calculate semantic similarity score
 * between article and user interest.
 */
const score = cosineSimilarity(articleEmb, interestEmb);

/**
 * Remove large/unnecessary metadata fields
 * from the original payload before returning.
 *
 * - keeps output clean
 * - avoids storing heavy embedding arrays
 * - keeps only useful article data + final score
 */
const {
  embeddings: _e,
  model: _m,
  total_duration: _td,
  load_duration: _ld,
  prompt_eval_count: _pc,
  created_at: _ca,
  done: _d,
  done_reason: _dr,
  // destructuring like this means "put in the articles constant all attributes that were not listed yet"
  ...article
} = $json;


/**
 * Return cleaned article object
 * with the new similarity score attached.
 */
return {
  json: {
    ...article,
    similarityScore: score
  }
};

// Remove any <think>...</think> sections from the LLM response
const cleanedResponse = ($json.response || '')
  .replace(/<think>[\s\S]*?<\/think>/g, '')
  .trim();

// Check if the LLM marked the article as relevant
// (assumes "YES" appears in the response when relevant)
const isRelevant = cleanedResponse.toUpperCase().includes('YES');

// Destructure to exclude all Ollama response metadata fields.
// $json here is the merged result of the Ollama response (input 0)
// and the original article data (input 1), so article fields are preserved.
const {
  response: _response,
  model: _model,
  total_duration: _totalDuration,
  load_duration: _loadDuration,
  prompt_eval_count: _promptEvalCount,
  prompt_eval_duration: _promptEvalDuration,
  eval_count: _evalCount,
  eval_duration: _evalDuration,
  created_at: _createdAt,
  done: _done,
  done_reason: _doneReason,
  context: _context,
  thinking: _thinking,
  ...articleData // remaining fields = actual article content
} = $json;

// Return cleaned article with relevance flag
return {
  json: {
    ...articleData,
    isRelevant,          // boolean from LLM classification
    filterMethod: 'llm'  // indicates filtering source
  }
};

